<?php
declare(strict_types=1);
if(!defined('CMS_ENTRY'))exit;
function snapshot(Store $store):array{return ['site'=>$store->get('site'),'pages'=>$store->get('pages',[]),'categories'=>$store->get('categories',[]),'links'=>$store->get('links',[]),'redirects'=>$store->get('redirects',[])];}
function publish(Store $store,string $actor,?array $snapshot=null):string{
 $snap=$snapshot??snapshot($store);if(!is_array($snap['pages']??null)||count($snap['pages'])>1000)fail(400,'Invalid publication snapshot.');$snap['pages']=array_map(fn($p)=>validate_page($p,$snap['pages'],$snap['categories']??[]),$snap['pages']);$snap['site']=validate_site($snap['site'],$snap['pages'],$snap['categories']??[]);$live=array_values(array_filter($snap['pages'],fn($p)=>$p['status']==='published'));if(!array_filter($live,fn($p)=>$p['slug']===''))fail(400,'A published homepage is required.');$id=uid();$dir=private_dir().'/releases/'.$id;mkdir($dir,0700,true);$all=all_pages($snap['site'],$snap['pages'],$snap['categories'],$snap['links']);
 try{foreach($all as $p){if($p['status']!=='published')continue;$file=$dir.($p['slug']?'/'.$p['slug']:'').'/index.html';if(!is_dir(dirname($file)))mkdir(dirname($file),0700,true);atomic_write($file,render_page($p,$snap['site'],$all,$snap['categories'],$snap['links']));}
 $search=[];$urls=[];foreach($all as $p){if($p['status']!=='published'||!empty($p['seo']['noindex']))continue;$urls[]='<url><loc>'.e(rtrim($snap['site']['url'],'/').page_path($p)).'</loc></url>';if(str_starts_with($p['id'],'generated-'))continue;$text=[$p['excerpt']??''];foreach($p['sections'] as $s){if(!empty($s['hidden']))continue;$text[]=$s['title']??'';$text[]=$s['text']??'';foreach($s['items']??[] as $i){$text[]=$i['title'];$text[]=$i['text'];}foreach($s['pricing']['plans']??[] as $plan){$text[]=$plan['name'];$text[]=$plan['price'];foreach($plan['features'] as $f)$text[]=$f['label'].' '.$f['value'];}}$search[]=['title'=>$p['title'],'url'=>local_url(page_path($p)),'text'=>mb_substr(implode(' ',$text),0,30000)];}
 atomic_write($dir.'/search-index.json',json_encode($search,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));atomic_write($dir.'/sitemap.xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'.implode('',$urls).'</urlset>');atomic_write($dir.'/robots.txt',"User-agent: *\nAllow: /\nDisallow: ".base_path()."/admin/\nDisallow: ".base_path()."/api/\nSitemap: ".$snap['site']['url']."/sitemap.xml\n");atomic_write($dir.'/snapshot.json',json_encode($snap,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));
 $store->tx(function()use($store,$id,$snap,$actor){$rows=$store->get('revisions',[]);array_unshift($rows,['id'=>$id,'created'=>stamp(),'snapshot'=>$snap]);$store->set('revisions',array_slice($rows,0,10));$store->set('current',$id);$store->audit($actor,'Published website');});return $id;
 }catch(Throwable $e){remove_private_tree($dir);throw $e;}
}
function remove_private_tree(string $path):void{if(!is_dir($path))return;$real=realpath($path);$root=realpath(private_dir());if(!$real||!$root||$real===$root||!inside($root,$real)||is_link($path))fail(500,'Unsafe storage operation refused.');foreach(new DirectoryIterator($real) as $file){if($file->isDot())continue;if($file->isLink()||$file->isFile())unlink($file->getPathname());elseif($file->isDir())remove_private_tree($file->getPathname());}rmdir($real);}
function zip_add_dir(ZipArchive $zip,string $directory,string $prefix):void{if(!is_dir($directory))return;$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory,FilesystemIterator::SKIP_DOTS));foreach($iterator as $file){if(!$file->isFile()||$file->isLink())continue;$relative=str_replace('\\','/',substr($file->getPathname(),strlen($directory)+1));if($relative==='snapshot.json')continue;$zip->addFile($file->getPathname(),$prefix.$relative);}}
function full_backup(Store $store,string $archivePassword=''):string{if($archivePassword!=='')validate_archive_password($archivePassword);$path=private_dir().'/backups/backup-'.gmdate('Ymd-His').'-'.uid().'.zip';$zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::EXCL)!==true)fail(500,'Cannot create backup.');$data=['format'=>'1ded-php-backup','schema'=>CMS_SCHEMA,'version'=>CMS_VERSION,'created'=>stamp(),'kv'=>$store->query('SELECT name,value FROM cms_kv')->fetchAll(),'users'=>$store->query('SELECT id,email,hash,role,recovery FROM cms_users')->fetchAll()];$data=security_backup($data);$zip->addFromString('backup.json',json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));zip_add_dir($zip,private_dir().'/media','media/');zip_add_dir($zip,private_dir().'/originals','originals/');if($archivePassword!==''){if(!ZipArchive::isEncryptionMethodSupported(ZipArchive::EM_AES_256)){ $zip->close();@unlink($path);fail(503,'This host does not support AES-256 ZIP encryption.');}if(!$zip->setPassword($archivePassword)){ $zip->close();@unlink($path);fail(500,'Could not configure backup encryption.');}for($i=0;$i<$zip->numFiles;$i++)if(!$zip->setEncryptionIndex($i,ZipArchive::EM_AES_256)){ $zip->close();@unlink($path);fail(500,'Could not encrypt every backup entry.');}}if(!$zip->close()){@unlink($path);fail(500,'Backup could not be finalized.');}chmod($path,0600);return $path;}
function static_export(Store $store):string{$current=$store->get('current');if(!$current||!preg_match('/^[a-f0-9]{32}$/D',$current))fail(400,'Publish first.');$snap=json_decode(file_get_contents(private_dir().'/releases/'.$current.'/snapshot.json'),true,128,JSON_THROW_ON_ERROR);$path=private_dir().'/backups/static-'.uid().'.zip';$zip=new ZipArchive();$zip->open($path,ZipArchive::CREATE|ZipArchive::EXCL);zip_add_dir($zip,private_dir().'/releases/'.$current,'');zip_add_dir($zip,CMS_ROOT.'/assets','assets/');$media=[];foreach([$snap['site']['logo']??'',$snap['site']['favicon']??'',$snap['site']['socialImage']??''] as $image)if(str_starts_with($image,'/media/'))$media[basename($image)]=true;foreach($snap['pages'] as $p)if($p['status']==='published'){if(str_starts_with($p['seo']['image']??'','/media/'))$media[basename($p['seo']['image'])]=true;foreach($p['sections'] as $s){if(!empty($s['hidden']))continue;foreach(array_merge([['image'=>$s['image']??'']],$s['items']??[]) as $item)if(str_starts_with($item['image']??'','/media/'))$media[basename($item['image'])]=true;}}
 foreach(array_keys($media) as $file)if(is_file(private_dir().'/media/'.$file))$zip->addFile(private_dir().'/media/'.$file,'media/'.$file);
 // Static export must not disclose admin code or depend on a missing inbox.
 $zip->deleteName('assets/admin.js');$zip->deleteName('assets/admin.css');$zip->addFromString('CONTACT-FORM.txt','This static export needs the configured live HTTPS form endpoint to receive messages. The PHP inbox is not included.');$zip->addFromString('.htaccess',"Options -Indexes\nDirectoryIndex index.html\n");$zip->close();chmod($path,0600);return $path;}
function download_zip(string $path,string $name,bool $remove=false):never{header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.$name.'"');header('Cache-Control: no-store');header('Content-Length: '.filesize($path));readfile($path);if($remove)unlink($path);exit;}
function restore_backup(Store $store,string $path,string $actor,string $archivePassword=''):string{
 if(filesize($path)>134217728)fail(413,'Backup exceeds 128 MB.');$zip=new ZipArchive();if($zip->open($path)!==true)fail(400,'Invalid ZIP backup.');if($archivePassword!==''){$archivePassword=validate_archive_password($archivePassword);$zip->setPassword($archivePassword);}$total=0;$entries=[];$metadata=null;
 try{if($zip->numFiles>5000)fail(400,'Too many backup entries.');for($i=0;$i<$zip->numFiles;$i++){$s=$zip->statIndex($i);$name=$s['name'];$total+=$s['size'];if($total>536870912||$s['size']>33554432)fail(413,'Expanded backup is too large.');if(isset($entries[$name]))fail(400,'Duplicate backup path.');$entries[$name]=$i;if($name==='backup.json')continue;if(!preg_match('~^(media|originals)/[a-f0-9]{32}\.(png|jpg|webp|gif)$~D',$name))fail(400,'Unexpected backup file.');}$raw=$zip->getFromName('backup.json');if(!$raw)fail(400,'Cannot read backup metadata. For an encrypted backup, enter its correct backup passphrase.');$metadata=json_decode($raw,true,128,JSON_THROW_ON_ERROR);if(($metadata['format']??'')!=='1ded-php-backup'||($metadata['schema']??0)!==CMS_SCHEMA)fail(400,'This backup is not compatible with this PHP edition.');if(!is_array($metadata['kv']??null)||!is_array($metadata['users']??null)||count($metadata['users'])>100)fail(400,'Invalid backup metadata.');$kv=[];foreach($metadata['kv'] as $row){if(!is_array($row)||!preg_match('/^[A-Za-z][A-Za-z0-9]*$/D',$row['name']??'')||!is_string($row['value']??null))fail(400,'Invalid backup data.');$kv[$row['name']]=json_decode($row['value'],true,128,JSON_THROW_ON_ERROR);}
 if(($kv['schema']??0)!==CMS_SCHEMA||!is_array($kv['pages']??null)||!is_array($kv['site']??null)||count($kv['pages'])>1000)fail(400,'Invalid backup content.');$pages=[];foreach($kv['pages'] as $p)$pages[]=validate_page($p,$kv['pages'],$kv['categories']??[]);$kv['pages']=$pages;$kv['site']=validate_site($kv['site'],$pages,$kv['categories']??[]);$owners=0;foreach($metadata['users'] as $u){if(!preg_match('/^[a-f0-9]{32}$/D',$u['id']??'')||!filter_var($u['email']??'',FILTER_VALIDATE_EMAIL)||!in_array($u['role']??'',['owner','editor'],true)||empty(password_get_info($u['hash']??'')['algo']))fail(400,'Invalid account data.');if($u['role']==='owner')$owners++;}if($owners<1)fail(400,'Backup contains no owner.');
 if(!is_array($kv['media']??null)||count($kv['media'])>3000)fail(400,'Invalid media metadata.');foreach($kv['media'] as &$media){if(!is_array($media)||!preg_match('/^[a-f0-9]{32}\.(png|jpg|webp|gif)$/D',$media['id']??'')||!preg_match('/^[a-f0-9]{32}\.(png|jpg|webp|gif)$/D',$media['sourceFile']??'')||!isset($entries['media/'.$media['id']],$entries['originals/'.$media['sourceFile']]))fail(400,'Backup media is missing or invalid.');$media['url']='/media/'.$media['id'];$media['sourceUrl']='/api/media-source/'.$media['id'];foreach(['name'=>150,'alt'=>500,'folder'=>100] as $key=>$limit)$media[$key]=txt($media[$key]??'',$limit);}unset($media);
 $incomingKey=security_restore_validate($metadata,$kv);$previousKey=is_file(private_dir().'/mfa.key')?file_get_contents(private_dir().'/mfa.key'):null;
 $stage=private_dir().'/restore-'.uid();mkdir($stage,0700);mkdir($stage.'/media',0700);mkdir($stage.'/originals',0700);foreach($entries as $name=>$i){if($name==='backup.json')continue;$bytes=$zip->getFromIndex($i);if($bytes===false)fail(400,'A backup entry is damaged.');$dims=@getimagesizefromstring($bytes);if(!$dims||$dims[0]*$dims[1]>40000000)fail(400,'A backup image is invalid.');atomic_write($stage.'/'.$name,$bytes);}$safety=full_backup($store);$old=private_dir().'/before-restore-'.uid();mkdir($old,0700);$operation=uid();restore_journal(['id'=>$operation,'stage'=>basename($stage),'old'=>basename($old),'previousKey'=>$previousKey===null?null:base64_encode($previousKey),'incomingCurrent'=>$kv['current']??null]);try{move_private(private_dir().'/media',$old.'/media');move_private(private_dir().'/originals',$old.'/originals');move_private($stage.'/media',private_dir().'/media');move_private($stage.'/originals',private_dir().'/originals');if($incomingKey!==null)atomic_write(private_dir().'/mfa.key',$incomingKey);$store->tx(function()use($store,$kv,$metadata,$actor,$operation){$store->query('DELETE FROM cms_sessions');$store->query('DELETE FROM cms_users');$store->query('DELETE FROM cms_kv');foreach($kv as $key=>$value){if(in_array($key,['backupTickets','maintenance','current','loginChallenges'],true))continue;$store->set($key,$value);}foreach($metadata['users'] as $u)$store->query('INSERT INTO cms_users(id,email,hash,role,recovery) VALUES (?,?,?,?,?)',[$u['id'],$u['email'],$u['hash'],$u['role'],$u['recovery']]);$store->set('restoreOperation',$operation);$store->set('current',null);$store->audit($actor,'Restored full backup; all sessions revoked');});}catch(Throwable $error){recover_interrupted_restore($store);throw $error;}
 recover_interrupted_restore($store);return basename($safety);
 }finally{$zip->close();if(isset($stage)&&is_dir($stage)&&!is_file(restore_journal_path()))remove_private_tree($stage);}
}

function move_private(string $from,string $to):void{if(!inside(realpath(private_dir()),$from)||!inside(realpath(private_dir()),$to)||is_link($from)||!@rename($from,$to))fail(500,'Storage move failed. Check permissions and the retained safety backup.');}

function validate_archive_password(mixed $password):string{if(!is_string($password)||strlen($password)<12||strlen($password)>256||str_contains($password,"\0"))fail(400,'Use a separate backup passphrase of 12–256 bytes.');return $password;}
